// Explota perfiles[] x keywords[] en un item por combinacion (perfil, keyword)
const cfg = $input.first().json;
const out = [];
for (const p of cfg.perfiles) {
  for (const kw of p.keywords) {
    out.push({ json: { perfil: p.perfil, keyword: kw, ubicacion: cfg.ubicacion, ubicacion_linkedin: cfg.ubicacion_linkedin, dominio: cfg.dominio } });
  }
}
return out;

// Parser sin dependencias externas (cheerio no viene instalado en n8n por defecto).
// Selectores verificados contra HTML real de www.magneto365.com/co (30/08/2026),
// validado contra archivo descargado por el usuario: 20/20 tarjetas parseadas OK.
// OJO: Magneto renderiza la fecha de publicacion por JS en el navegador
// (bailout to client-side rendering), no esta disponible en el HTML estatico.
const ctx = $('Loop (rate limit) Magneto').item.json;
const html = $input.first().json.data || $input.first().json.body || '';

function decodeEntities(str) {
  return str
    .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'");
}

const out = [];
const cards = html.split('<article class="mg_job_card_desktop_magneto-ui-card-jobs_13c81').slice(1);

for (const block of cards) {
  const aMatch = block.match(/<a href="([^"]+)" title="([^"]+)"[^>]*class="mg_job_card_desktop_magneto-ui-card-jobs_a_13c81"/);
  if (!aMatch) continue;
  const url = aMatch[1];
  const titulo = decodeEntities(aMatch[2]);

  const h3Match = block.match(/<h3 class="mg_job_card_desktop_magneto-ui-card-jobs_text_13c81 ">([^<]*)<\/h3>/);
  const empresaRaw = h3Match ? decodeEntities(h3Match[1]).trim() : '';
  const empresa = empresaRaw.split('|')[0].trim();

  const pMatches = [...block.matchAll(/<p class="mg_job_card_desktop_magneto-ui-card-jobs_text_13c81 ">([^<]*)<\/p>/g)];
  const ubicacion = pMatches.length > 1 ? decodeEntities(pMatches[1][1]).trim() : '';

  out.push({ json: {
    fuente: 'Magneto365', titulo, empresa, ubicacion, fecha_publicacion: '', url,
    perfil: ctx.perfil, keyword: ctx.keyword
  }});
}

return out;

const cfg = $('Config (perfiles + criterios) Magneto').first().json;
// Puestos a descartar (seniority, idioma...). Se puede reemplazar con EXCLUIR_PUESTO_REGEX en el .env
const EXCLUIR_PUESTO = cfg.excluir_puesto_regex ? new RegExp(cfg.excluir_puesto_regex, 'i') : /(pasant[ií]a|practicante|trainee|sin experiencia|reci[eé]n egresado|aprendiz|ingl[eé]s avanzado|ingl[eé]s fluido|\bc1\b|\bc2\b)/i;

// Rubros a descartar. Se puede reemplazar con EXCLUIR_RUBRO_REGEX en el .env
const EXCLUIR_RUBRO = cfg.excluir_rubro_regex ? new RegExp(cfg.excluir_rubro_regex, 'i') : /(cocin|chef|mozo|moza|camarer|gastronom|restaurant|barista|bartender|cadete|repartidor|hotel|hoteler|mucama|cajer|g[oó]ndola|supermercado|kiosco|vigilador|vigilancia|personal de limpieza)/i;

// Zona aceptada (ciudad, remoto, hibrido): ZONA_REGEX en el .env
const ZONA_OK = new RegExp(cfg.zona_regex || '.', 'i');

// Magneto no expone la fecha en el HTML estatico (se renderiza por JS en el navegador),
// asi que no filtramos por fecha aca: solo por puesto, rubro y zona.
// En Magneto la fecha no suele venir en el HTML estatico, pero si llega se valida maximo 3 dias
const FECHA_VIEJA = /hace\s+([4-9]|\d{2,})\s*d[ií]as?|semana|mes|año/i;
const FECHA_OK = /^$|ahora|minuto|hora|ayer|hoy|hace\s+[1-3]\s*d[ií]as?\b/i;

// Descarta si menciona explicitamente un salario mensual menor a SALARIO_MINIMO (.env)
const SALARIO_MINIMO = Number($env.SALARIO_MINIMO || 0);
function salarioEsBajo(t) {
  if (!t || !SALARIO_MINIMO) return false;
  const str = String(t).toLowerCase();
  if (/salario\s+m[ií]nimo|smlv|m[ií]nimo\s+legal/i.test(str)) return true;
  const mMillones = str.match(/(\d+(?:[.,]\d+)?)\s*(?:mill[oó]n|millones|m\b)/i);
  if (mMillones) {
    const val = parseFloat(mMillones[1].replace(',', '.'));
    if (val > 0 && val * 1e6 < SALARIO_MINIMO) return true;
  }
  const mNums = str.match(/\$?\s*(\d{1,2}[.\s]?\d{3}[.\s]?\d{3})/g);
  if (mNums) {
    for (const m of mNums) {
      const num = parseInt(m.replace(/[^\d]/g, ''), 10);
      if (num >= 500000 && num < SALARIO_MINIMO) return true;
    }
  }
  return false;
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.url) continue;
  const texto = `${j.titulo} ${j.empresa} ${j.ubicacion}`;
  if (EXCLUIR_PUESTO.test(texto)) continue;
  if (EXCLUIR_RUBRO.test(texto)) continue;
  if (!ZONA_OK.test(j.ubicacion || '')) continue;
  if (j.fecha_publicacion && FECHA_VIEJA.test(j.fecha_publicacion)) continue;
  if (!FECHA_OK.test((j.fecha_publicacion || '').trim())) continue;
  if (salarioEsBajo(texto)) continue;
  out.push({ json: j });
}
return out;

const filtradas = $('Filtrar (descartar dealbreakers) Magneto').all();

// URLs ya guardadas con un match valido -> se saltean.
// Las que quedaron con un error transitorio de la IA (ats_tip empieza con "ERROR")
// NO se excluyen, para que la proxima corrida las vuelva a evaluar en vez de perderlas para siempre.
const existentes = new Set(
  $('Leer URLs ya guardadas Magneto').all()
    .filter(i => i.json.url && !String(i.json.ats_tip || '').startsWith('ERROR'))
    .map(i => i.json.url)
);

const sd = $getWorkflowStaticData('global');
if (!sd.urlsEstaCorrida) sd.urlsEstaCorrida = [];
const vistasEstaCorrida = new Set(sd.urlsEstaCorrida);

const nuevas = [];
for (const item of filtradas) {
  const url = item.json.url;
  if (!url) continue;
  if (existentes.has(url) || vistasEstaCorrida.has(url)) continue;
  vistasEstaCorrida.add(url);
  nuevas.push(item);
}
sd.urlsEstaCorrida = Array.from(vistasEstaCorrida);

return nuevas;

// Evalua las ofertas nuevas contra la HV con Gemini y deja pasar SOLO las mejores:
// maximo `max_ofertas` (5) con match >= `umbral_match` (90). El resto no se guarda en la
// planilla, pero queda registrado como "ya evaluado" para no gastar cuota en la proxima corrida.
// Para no pasarse de la cuota de la API, las ofertas se puntuan en lotes (varias por llamada).
const cfg = $('Config (perfiles + criterios) Magneto').first().json;
// Salario mensual minimo aceptado (.env); vacio = no se filtra por salario
const SALARIO_MINIMO_IA = Number($env.SALARIO_MINIMO || 0);
// ---- Utilidades compartidas: Gemini (API de Google AI Studio) + lectura de ofertas ----
// Presupuesto de tiempo: n8n corta el nodo a los 15 min (N8N_RUNNERS_TASK_TIMEOUT) y, al
// cortarlo, reinicia el ejecutor y aborta tareas de otros workflows. A los 11 min se deja de
// llamar a Gemini: lo no evaluado no se marca y se reintenta en la próxima corrida.
const LIMITE = Date.now() + 11 * 60 * 1000;
const helpers = this.helpers;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Llama a Gemini por su endpoint compatible con OpenAI. Reintenta ante 429/5xx y, si el
// modelo principal sigue fallando (cuota o saturacion), cae a los modelos "lite" (cuota aparte).
async function gemini(prompt, { maxTokens = 8192, json = false } = {}) {
  const key = String(cfg.gemini_api_key || '').trim();
  if (!key) throw new Error('GEMINI_API_KEY vacia: revisa el .env y reinicia el contenedor (docker compose up -d).');
  const modelos = [cfg.gemini_model || 'gemini-3.8-flash', 'gemini-flash-lite-latest', 'gemini-3.5-flash-lite'];
  let err = '';
  for (let intento = 0; intento < 5; intento++) {
    if (Date.now() > LIMITE) { err = err || 'sin tiempo para mas llamadas a Gemini'; break; }
    const model = modelos[[0, 0, 1, 1, 2][intento]];
    try {
      const body = { model, messages: [{ role: 'user', content: prompt }], max_tokens: maxTokens, temperature: 0.2, reasoning_effort: 'low' };
      if (json) body.response_format = { type: 'json_object' };
      const resp = await helpers.httpRequest({
        method: 'POST',
        url: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
        headers: { Authorization: 'Bearer ' + key, 'content-type': 'application/json' },
        body,
        json: true,
        timeout: 120000
      });
      const choice = (resp.choices || [])[0];
      const texto = ((choice && choice.message && choice.message.content) || '').trim();
      if (texto) return { texto, err: '' };
      err = 'Gemini sin texto: ' + JSON.stringify(resp).slice(0, 200);
    } catch (e) {
      err = (e.message || String(e)).slice(0, 300);
    }
    await sleep(intento === 0 ? 10000 : 25000);
  }
  return { texto: '', err };
}

function decodeEntities(str) {
  return String(str)
    .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'");
}
function limpiarHtml(str) {
  return decodeEntities(String(str)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

// Saca la descripcion de la oferta. Primero intenta el JSON-LD "JobPosting" (LinkedIn,
// Computrabajo y Elempleo lo publican), que trae solo la descripcion sin menus ni footer;
// si no esta, usa el texto plano de toda la pagina.
function extraerDescripcion(html, maxChars) {
  const s = String(html || '');
  const bloques = s.match(/<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/gi) || [];
  for (const b of bloques) {
    try {
      const data = JSON.parse(b.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, ''));
      const lista = Array.isArray(data) ? data : (data['@graph'] || [data]);
      for (const d of lista) {
        if (d && d.description && /JobPosting/i.test(String(d['@type'] || ''))) {
          return limpiarHtml(decodeEntities(d.description)).slice(0, maxChars);
        }
      }
    } catch (e) { /* JSON-LD invalido: probar el siguiente */ }
  }
  return limpiarHtml(s).slice(0, maxChars);
}

async function traerDescripcion(url, maxChars) {
  try {
    const resp = await helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'es-CO,es;q=0.9,en;q=0.8',
        'Referer': 'https://www.google.com/'
      },
      timeout: 20000
    });
    const raw = (resp && (resp.body || resp.data)) || resp || '';
    return extraerDescripcion(typeof raw === 'string' ? raw : JSON.stringify(raw), maxChars);
  } catch (e) {
    return '';
  }
}

const HV = String(cfg.hv_base || '').replace(/\\n/g, '\n').trim();
if (!HV) throw new Error('HV_BASE_TEXT esta vacio: revisa el .env (debe ir en su propia linea) y reinicia el contenedor.');
const UMBRAL = Number(cfg.umbral_match) || 83;
const MAX_OFERTAS = Number(cfg.max_ofertas) || 5;
const MAX_CANDIDATOS = Number(cfg.max_candidatos) || 30;
const LOTE = 8;
const DESC_CHARS = 1800;

// URLs evaluadas en corridas anteriores (se olvidan a los 21 dias)
const sd = $getWorkflowStaticData('global');
const evaluadas = sd.evaluadas || {};
const ahora = Date.now();
for (const [u, t] of Object.entries(evaluadas)) {
  if (ahora - t > 21 * 24 * 3600 * 1000) delete evaluadas[u];
}

// Pre-orden barato (sin IA): primero los titulos que contienen mas palabras de las keywords (PERFILES_BUSQUEDA)
const PALABRAS = [...new Set((cfg.perfiles || []).flatMap((p) => p.keywords || []).flatMap((k) => String(k).toLowerCase().split(/\s+/)).filter((w) => w.length > 2))];
const RELEVANTE = PALABRAS.length ? new RegExp('(' + PALABRAS.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')', 'gi') : /./g;
const candidatos = $input.all()
  .map((i) => i.json)
  .filter((j) => j.url && !evaluadas[j.url])
  .map((j) => ({ j, peso: (String(j.titulo || '').match(RELEVANTE) || []).length }))
  .sort((a, b) => b.peso - a.peso)
  .slice(0, MAX_CANDIDATOS)
  .map((x) => x.j);

if (!candidatos.length) return [];

// 1) Descripciones (de a 4 en paralelo para no saturar el sitio ni la VM)
for (let i = 0; i < candidatos.length; i += 4) {
  const grupo = candidatos.slice(i, i + 4);
  const descs = await Promise.all(grupo.map((c) => traerDescripcion(c.url, DESC_CHARS)));
  grupo.forEach((c, k) => { c.desc = descs[k].length >= 100 ? descs[k] : '(sin descripcion, evaluar solo por el titulo)'; });
}

// 2) Puntaje por lotes
const puntuadas = [];
let ultimoError = '';
for (let i = 0; i < candidatos.length; i += LOTE) {
  if (Date.now() > LIMITE) { ultimoError = ultimoError || 'sin tiempo: el resto se evalua en la proxima corrida'; break; }
  const lote = candidatos.slice(i, i + LOTE);
  const prompt = [
    'Eres un reclutador tecnico' + (cfg.pais ? ' en ' + cfg.pais : '') + '. Evalua que tan compatible es la hoja de vida (HV) del candidato con CADA oferta.',
    'REGLAS DE EVALUACION:',
    '1. Compatibilidad: Se riguroso. Asigna 83 o mas solo si el candidato cumple los requisitos principales (rol, anios de experiencia, herramientas, ingles, ubicacion/modalidad). Si pide algo critico que la HV no tiene, el puntaje debe ser menor a 75.',
    '2. Filtro obligatorio de salario: ' + (SALARIO_MINIMO_IA
      ? `Si la oferta menciona explicitamente un salario o rango mensual inferior a ${SALARIO_MINIMO_IA.toLocaleString('es')} (ej: el salario minimo legal o cifras menores), asignale OBLIGATORIAMENTE match = 0 para descartarla. Si el salario no esta especificado, es confidencial o a convenir, o si es igual o mayor, calificala normalmente con su compatibilidad real.`
      : 'No descartes ofertas por salario: calificalas por su compatibilidad real.'),
    'Responde SOLO con JSON valido, sin markdown, con este formato exacto:',
    '{"resultados": [{"id": <id de la oferta>, "match": <entero 0-100>, "tip": "<max 15 palabras: keyword de la oferta que conviene resaltar en la HV>"}]}',
    'Incluye un resultado por cada oferta.',
    '',
    '=== HV DEL CANDIDATO ===',
    HV,
    '',
    '=== OFERTAS ===',
    ...lote.map((c, k) => [
      '--- id: ' + (k + 1) + ' ---',
      'Puesto: ' + (c.titulo || ''),
      'Empresa: ' + (c.empresa || ''),
      'Ubicacion: ' + (c.ubicacion || ''),
      'Descripcion: ' + c.desc
    ].join('\n'))
  ].join('\n');

  const r = await gemini(prompt, { maxTokens: 4096, json: true });
  let resultados = [];
  try {
    const jm = r.texto.match(/\{[\s\S]*\}/);
    resultados = JSON.parse(jm ? jm[0] : r.texto).resultados || [];
  } catch (e) { resultados = []; }

  lote.forEach((c, k) => {
    const res = resultados.find((x) => Number(x.id) === k + 1);
    if (!res || res.match === undefined || res.match === null || isNaN(Number(res.match))) return; // se reintenta la proxima corrida
    evaluadas[c.url] = ahora;
    puntuadas.push({ ...c, match_pct: Math.round(Number(res.match)), ats_tip: String(res.tip || '') });
  });
  if (!resultados.length) ultimoError = r.err || ('respuesta no interpretable: ' + r.texto.slice(0, 200));

  if (i + LOTE < candidatos.length) await sleep(7000); // respeta el limite de peticiones por minuto
}
sd.evaluadas = evaluadas;
// Si la IA no pudo puntuar NADA, que la ejecucion quede en rojo en n8n (y no "exitosa" sin datos)
if (!puntuadas.length && ultimoError) throw new Error('Gemini no pudo evaluar ninguna oferta: ' + ultimoError);

// 3) Top N por encima del umbral
// Descarta si menciona explicitamente un salario mensual menor a SALARIO_MINIMO (.env)
const SALARIO_MINIMO = Number($env.SALARIO_MINIMO || 0);
function salarioEsBajo(t) {
  if (!t || !SALARIO_MINIMO) return false;
  const str = String(t).toLowerCase();
  if (/salario\s+m[ií]nimo|smlv|m[ií]nimo\s+legal/i.test(str)) return true;
  const mMillones = str.match(/(\d+(?:[.,]\d+)?)\s*(?:mill[oó]n|millones|m\b)/i);
  if (mMillones) {
    const val = parseFloat(mMillones[1].replace(',', '.'));
    if (val > 0 && val * 1e6 < SALARIO_MINIMO) return true;
  }
  const mNums = str.match(/\$?\s*(\d{1,2}[.\s]?\d{3}[.\s]?\d{3})/g);
  if (mNums) {
    for (const m of mNums) {
      const num = parseInt(m.replace(/[^\d]/g, ''), 10);
      if (num >= 500000 && num < SALARIO_MINIMO) return true;
    }
  }
  return false;
}

return puntuadas
  .filter((p) => p.match_pct >= UMBRAL && !salarioEsBajo(p.desc))
  .sort((a, b) => b.match_pct - a.match_pct)
  .slice(0, MAX_OFERTAS)
  .map((p) => {
    const { desc, ...resto } = p;
    return { json: resto };
  });
